extends Control

@onready var grid_container: GridContainer = $GridContainer

const GALLERY_CATALOG: Array[Dictionary] = [
	{
		"id": "bg_archivio",
		"title": "L'Archivio",
		"texture_path": "res://assets/sprites/background.png"
	},
